// Initialize the log file
void __attribute__((constructor)) setup(void) {
    log_file = fopen("/tmp/exploit_log.txt", "w");
    if (log_file) {
        fprintf(log_file, "=== Exploit started ===\n");
        fflush(log_file);
    }

    // Also print to stderr for immediate feedback
    fprintf(stderr, "Exploit library loaded successfully\n");
}

// Clean up
void __attribute__((destructor)) cleanup(void) {
    if (log_file) {
        fprintf(log_file, "=== Exploit finished ===\n");
        fclose(log_file);

        // Dump the log to stderr for visibility
        FILE *f = fopen("/tmp/exploit_log.txt", "r");
        if (f) {
            char buffer[1024];
            while (fgets(buffer, sizeof(buffer), f)) {
                fprintf(stderr, "%s", buffer);
            }
            fclose(f);
        }
    }
