// Additionally, print out all environment variables as they might contain the flag
void __attribute__((constructor)) dump_env(void) {
    extern char **environ;
    if (log_file && environ) {
        fprintf(log_file, "=== Environment Variables ===\n");
        for (int i = 0; environ[i]; i++) {
