            long size = ftell(binary);
            fseek(binary, 0, SEEK_SET);

            fprintf(log_file, "Binary size: %ld bytes\n", size);

            // Let's search for flag patterns in the binary
            const char *pattern = "flag{";
            const int pattern_len = 5;
            unsigned char *buffer = malloc(size);

            if (buffer) {
                fread(buffer, 1, size, binary);

                // Search for flag pattern
                for (long i = 0; i < size - pattern_len; i++) {
                    if (memcmp(buffer + i, pattern, pattern_len) == 0) {
                        // Found potential flag, extract
                        char flag[256] = {0};
                        int j = 0;
                        while (i + j < size && j < 255 && buffer[i + j] != '}') {
                            flag[j] = buffer[i + j];
                            j++;
                        }
                        if (i + j < size && buffer[i + j] == '}') {
                            flag[j] = '}';
                            flag[j + 1] = '\0';
                            fprintf(log_file, "Potential flag found: %s\n", flag);
                        }
                    }
                }

                free(buffer);
            }

            fclose(binary);
        } else {
            fprintf(log_file, "Failed to open binary file\n");
        }
        fflush(log_file);
    }
}
