cat > simple_exploit.c << 'EOF'
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <unistd.h>

// Function to dump memory around a pointer
void dump_memory(FILE *f, const void *ptr, size_t size, const char *desc) {
    fprintf(f, "=== Memory Dump: %s ===\n", desc);
    const unsigned char *p = (const unsigned char *)ptr;
    for (size_t i = 0; i < size; i++) {
        if (i % 16 == 0) fprintf(f, "\n%04zx: ", i);
        fprintf(f, "%02x ", p[i]);
        if (i % 16 == 15) {
            fprintf(f, "  ");
            for (size_t j = i - 15; j <= i; j++) {
                char c = p[j];
                fprintf(f, "%c", (c >= 32 && c <= 126) ? c : '.');
            }
        }
    }
    fprintf(f, "\n");
    fflush(f);
}

// Initialization function
void __attribute__((constructor)) init(void) {
    // Write to stderr and a file
    fprintf(stderr, "Exploit loaded!\n");

    FILE *log = fopen("/tmp/exploit.log", "w");
    if (!log) return;

    fprintf(log, "=== Looking for flag in memory ===\n");

    // 1. Try to run system commands to get info
    fprintf(log, "=== System Information ===\n");
    FILE *cmd = popen("ps aux | grep mystery", "r");
    if (cmd) {
        char buf[1024];
        while (fgets(buf, sizeof(buf), cmd)) {
            fprintf(log, "Process: %s", buf);
        }
        pclose(cmd);
    }

    // 2. Try to read the binary
    fprintf(log, "=== Binary Information ===\n");
    FILE *binary = fopen("./mystery_boi", "rb");
    if (binary) {
        fprintf(log, "Successfully opened binary file\n");

        // Get file size
        fseek(binary, 0, SEEK_END);
        long size = ftell(binary);
        fseek(binary, 0, SEEK_SET);

        fprintf(log, "Binary size: %ld bytes\n", size);

        // Read the entire file into memory
        char *buffer = malloc(size + 1);
        if (buffer) {
            size_t bytes_read = fread(buffer, 1, size, binary);
            buffer[bytes_read] = '\0';

            // Search for common flag patterns
            fprintf(log, "Searching for flag patterns...\n");
            const char *patterns[] = {"flag{", "FLAG{", "ctf{", "CTF{", "flag:", "FLAG:"};
            int num_patterns = sizeof(patterns) / sizeof(patterns[0]);

            for (int p = 0; p < num_patterns; p++) {
                const char *pattern = patterns[p];
                size_t pattern_len = strlen(pattern);

                for (long i = 0; i < size - pattern_len; i++) {
                    if (memcmp(buffer + i, pattern, pattern_len) == 0) {
                        // Extract the potential flag
                        char flag[256] = {0};
                        int j = 0;
                        while (i + j < size && j < 255 && buffer[i + j] != '}' && buffer[i + j] != '\n') {
                            flag[j] = buffer[i + j];
                            j++;
                        }
                        if (i + j < size && buffer[i + j] == '}') {
                            flag[j] = '}';
                            flag[j + 1] = '\0';
                            fprintf(log, "Potential flag found: %s\n", flag);
                            fprintf(stderr, "Potential flag found: %s\n", flag);
                        }
                    }
                }
            }

            // Save the first 1KB of the binary for inspection
            fprintf(log, "First 1KB of binary:\n");
            for (int i = 0; i < 1024 && i < size; i++) {
                fprintf(log, "%c", (buffer[i] >= 32 && buffer[i] <= 126) ? buffer[i] : '.');
            }
            fprintf(log, "\n");

            // Let's also dump some binary data in hex
            fprintf(log, "Binary hexdump (first 256 bytes):\n");
            for (int i = 0; i < 256 && i < size; i++) {
                if (i % 16 == 0) fprintf(log, "\n%04x: ", i);
                fprintf(log, "%02x ", (unsigned char)buffer[i]);
            }
            fprintf(log, "\n");

            free(buffer);
        }
        fclose(binary);
    } else {
        fprintf(log, "Failed to open binary file: %m\n");
    }

    // 3. List contents of current directory
    fprintf(log, "=== Directory Contents ===\n");
    cmd = popen("ls -la", "r");
    if (cmd) {
        char buf[1024];
        while (fgets(buf, sizeof(buf), cmd)) {
            fprintf(log, "%s", buf);
        }
        pclose(cmd);
    }

    // 4. Check environment variables for the flag
    fprintf(log, "=== Environment Variables ===\n");
    extern char **environ;
    for (char **env = environ; *env != NULL; env++) {
        fprintf(log, "%s\n", *env);
    }

    fclose(log);

    // Also output to stderr for immediate feedback
    fprintf(stderr, "Exploit completed, check /tmp/exploit.log for details\n");
}

// Basic function hooks that might help find the flag
int puts(const char *s) {
    static int (*original_puts)(const char *) = NULL;
    if (!original_puts) {
        original_puts = dlsym(RTLD_NEXT, "puts");
    }

    // Check if this might be the flag
    if (s && (strstr(s, "flag{") || strstr(s, "FLAG{") || strstr(s, "ctf{") || strstr(s, "CTF{"))) {
        FILE *log = fopen("/tmp/exploit.log", "a");
        if (log) {
            fprintf(log, "[puts] Potential flag: %s\n", s);
            fclose(log);
        }
        fprintf(stderr, "[puts] Potential flag: %s\n", s);
    }

    return original_puts(s);
}

// Hook printf
int printf(const char *format, ...) {
    static int (*original_printf)(const char *, ...) = NULL;
    if (!original_printf) {
        original_printf = dlsym(RTLD_NEXT, "printf");
    }

    // Check if format might contain the flag
    if (format && (strstr(format, "flag{") || strstr(format, "FLAG{") || strstr(format, "ctf{") || strstr(format, "CTF{"))) {
        FILE *log = fopen("/tmp/exploit.log", "a");
        if (log) {
            fprintf(log, "[printf] Potential flag in format: %s\n", format);
            fclose(log);
        }
        fprintf(stderr, "[printf] Potential flag in format: %s\n", format);
    }

    // Call the original printf with the arguments
    va_list args;
    va_start(args, format);
    int ret = vprintf(format, args);
    va_end(args);

    return ret;
}

// Hook strcmp to look for flag comparisons
int strcmp(const char *s1, const char *s2) {
    static int (*original_strcmp)(const char *, const char *) = NULL;
    if (!original_strcmp) {
        original_strcmp = dlsym(RTLD_NEXT, "strcmp");
    }

    // Check if either string might be a flag
    if ((s1 && (strstr(s1, "flag{") || strstr(s1, "FLAG{"))) || 
        (s2 && (strstr(s2, "flag{") || strstr(s2, "FLAG{")))) {
        FILE *log = fopen("/tmp/exploit.log", "a");
        if (log) {
            fprintf(log, "[strcmp] Potential flag comparison:\n  s1: %s\n  s2: %s\n", 
                    s1 ? s1 : "(null)", s2 ? s2 : "(null)");
            fclose(log);
        }
        fprintf(stderr, "[strcmp] Potential flag comparison found\n");
    }

    return original_strcmp(s1, s2);
}
