            unsigned long end_addr = strtoul(end_str + 1, NULL, 16);

            // Scan these memory regions for flag patterns
            for (unsigned long addr = start_addr; addr < end_addr; addr += 4) {
                // Check if memory is accessible
                if (*(char*)addr == 'f' && *(char*)(addr+1) == 'l' && 
                    *(char*)(addr+2) == 'a' && *(char*)(addr+3) == 'g') {

                    // We found a potential flag, capture up to 100 chars
                    char potential_flag[100];
                    int i;
                    for (i = 0; i < 99; i++) {
                        char c = *(char*)(addr + i);
                        if (c == 0 || c == '\n') break;
                        potential_flag[i] = c;
                    }
                    potential_flag[i] = '\0';

                    FILE *f = fopen("/tmp/flag_found.txt", "a");
                    if (f) {
                        fprintf(f, "POTENTIAL FLAG: %s\n", potential_flag);
                        fclose(f);
                    }
                }
            }
        }
