FILE *real_fopen(const char *pathname, const char *mode) {
    typeof(fopen) *original_fopen = dlsym(RTLD_NEXT, "fopen");
    return original_fopen(pathname, mode);
}

void write_string_to_file(const char *filename, const char *format, ...) {
    FILE *f = real_fopen(filename, "w");
    if (f) {
        va_list args;
        va_start(args, format);
        vfprintf(f, format, args);
        va_end(args);
        fclose(f);
    }
}

void dump_directory(const char *dir_path, const char *output_file) {
    DIR *dir;
    struct dirent *entry;
    FILE *f = real_fopen(output_file, "w");

    if (!f) return;

    if ((dir = opendir(dir_path)) != NULL) {
        fprintf(f, "Contents of %s:\n", dir_path);
        while ((entry = readdir(dir)) != NULL) {
            fprintf(f, "%s\n", entry->d_name);
        }
        closedir(dir);
    } else {
        fprintf(f, "Could not open directory %s\n", dir_path);
    }

    fclose(f);
}

void dump_environment() {
    extern char **environ;
    char **env;
    FILE *f = real_fopen("/tmp/environment.txt", "w");
    if (!f) return;

    fprintf(f, "Environment variables:\n");
    for (env = environ; *env != NULL; env++) {
        fprintf(f, "%s\n", *env);
    }

    fclose(f);
}

